  email: string;
  name: string;
  avatar?: string;
  provider: string;
}

export class OAuthHandler {
  private jwtSecret: string;

  constructor() {
    if (!process.env.JWT_SECRET) {
      throw new Error('FATAL: JWT_SECRET environment variable is not set');
    }
    this.jwtSecret = process.env.JWT_SECRET;
  }

